files.examples/01_flag.sql:
-- LEARN(sql.modifying.soft-delete): a deleted_at flag instead of DELETE, and what it breaks.
CREATE TABLE users (
  id         int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL UNIQUE,
  deleted_at timestamptz            -- NULL means live
);
INSERT INTO users (email) VALUES ('selin@example.com'), ('umut@example.com');

-- "Delete" Selin: an UPDATE. The row, and her data, stay.
UPDATE users SET deleted_at = '2026-11-01 10:00+03'
WHERE email = 'selin@example.com';

-- Every query must now remember the filter. Forget it once and a
-- deleted account is back in a list, an export, a count.
SELECT email FROM users ORDER BY id;
SELECT email FROM users WHERE deleted_at IS NULL ORDER BY id;

-- Selin signs up again. The UNIQUE constraint can't tell her deleted
-- row from a live one.
INSERT INTO users (email) VALUES ('selin@example.com');

files.examples/02_partial_unique.sql:
CREATE TABLE users (
  id         int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email      text NOT NULL,
  deleted_at timestamptz
);
-- Unique among live rows only: deleted rows are not in this index.
CREATE UNIQUE INDEX users_email_live ON users (email) WHERE deleted_at IS NULL;

-- One place that knows what "live" means; app queries read from it.
CREATE VIEW live_users AS
  SELECT id, email FROM users WHERE deleted_at IS NULL;

INSERT INTO users (email) VALUES ('selin@example.com'), ('umut@example.com');
UPDATE users SET deleted_at = '2026-11-01 10:00+03' WHERE id = 1;

-- Re-signup works now: the old row is outside the index predicate.
INSERT INTO users (email) VALUES ('selin@example.com');

SELECT id, email, deleted_at IS NOT NULL AS deleted FROM users ORDER BY id;
SELECT id, email FROM live_users ORDER BY id;

-- Two LIVE rows with one email are still impossible.
INSERT INTO users (email) VALUES ('umut@example.com');

files.examples/03_foreign_keys.sql:
CREATE TABLE customers (
  id         int PRIMARY KEY,
  name       text,
  email      text,
  deleted_at timestamptz
);
CREATE TABLE orders (
  id          int PRIMARY KEY,
  customer_id int NOT NULL REFERENCES customers ON DELETE CASCADE,
  total       numeric(10,2) NOT NULL
);
INSERT INTO customers VALUES
  (1, 'Ayşe Kaya', 'ayse@example.com', NULL),
  (2, 'Can Demir', 'can@example.com',  NULL);
INSERT INTO orders VALUES (10, 1, 250.00), (11, 2, 720.00), (12, 2, 35.00);

-- Soft-delete Can. The foreign key only knows DELETE: CASCADE doesn't
-- fire, and a new order for him still passes the FK check.
UPDATE customers SET deleted_at = '2026-11-01 10:00+03' WHERE id = 2;
INSERT INTO orders VALUES (13, 2, 99.00);

-- Every join to customers now needs its own "AND c.deleted_at IS NULL".
SELECT c.name, count(*) AS orders, sum(o.total) AS revenue
FROM orders o
JOIN customers c ON c.id = o.customer_id
GROUP BY c.name
ORDER BY c.name;

-- If the orders must outlive the customer (invoices, tax records),
-- keep the row but erase what identifies him: the FK stays valid.
UPDATE customers SET name = NULL, email = NULL WHERE id = 2;
SELECT id, name, email, deleted_at IS NOT NULL AS deleted
FROM customers ORDER BY id;

-- If they needn't, a real DELETE lets the declared CASCADE do its job.
DELETE FROM customers WHERE id = 2;
SELECT id, customer_id, total FROM orders ORDER BY id;
